class DriftState(Enum):
    """State machine states for drift detection."""
    NORMAL = auto()
    WARNING = auto()
    DRIFT = auto()


@dataclass(frozen=True)
class DriftDetectorConfig:
    """Configuration for drift detector, mirroring Rust struct."""
    target_mean: float = 0.0
    epsilon: float = 0.1
    threshold: float = 5.0
    min_observations: int = 30

    def __post_init__(self):
        """Validate configuration invariants."""
        if self.epsilon <= 0:
            raise ValueError(f"epsilon must be positive, got {self.epsilon}")
        if self.threshold <= 0:
            raise ValueError(f"threshold must be positive, got {self.threshold}")
        if self.min_observations < 1:
            raise ValueError(
                f"min_observations must be >= 1, got {self.min_observations}"
            )


class DriftDetector:
    """CUSUM-based drift detector with state machine."""

    def __init__(self, config: Optional[DriftDetectorConfig] = None):
        self.config = config or DriftDetectorConfig()
        self._s_plus: float = 0.0
        self._s_minus: float = 0.0
        self._observation_count: int = 0
        self._state: DriftState = DriftState.NORMAL
        self._history: List[float] = []

    @property
    def state(self) -> DriftState:
        return self._state

    @property
    def s_plus(self) -> float:
        return self._s_plus

    @property
    def s_minus(self) -> float:
        return self._s_minus

    @property
    def observation_count(self) -> int:
        return self._observation_count

    def reset(self) -> None:
        """Reset detector to initial state."""
        self._s_plus = 0.0
        self._s_minus = 0.0
        self._observation_count = 0
        self._state = DriftState.NORMAL
        self._history.clear()

    def update(self, value: float) -> DriftState:
        """
        Process a new observation and return the resulting state.

        Implements the CUSUM algorithm:
        S+ = max(0, S+ + (x - target_mean) - epsilon)
        S- = max(0, S- - (x - target_mean) - epsilon)
        """
        if math.isnan(value):
            raise ValueError("Cannot process NaN observation")
        if math.isinf(value):
            raise ValueError(f"Cannot process infinite observation: {value}")

        self._history.append(value)
        self._observation_count += 1

        deviation = value - self.config.target_mean

        # CUSUM update
        self._s_plus = max(0.0, self._s_plus + deviation - self.config.epsilon)
        self._s_minus = max(0.0, self._s_minus - deviation - self.config.epsilon)

        # State transition logic
        if self._observation_count < self.config.min_observations:
            self._state = DriftState.NORMAL
        elif self._s_plus > self.config.threshold or self._s_minus > self.config.threshold:
            self._state = DriftState.DRIFT
        elif self._s_plus > 0 or self._s_minus > 0:
            self._state = DriftState.WARNING
        else:
            self._state = DriftState.NORMAL

        return self._state

    def process_stream(self, values: Iterator[float]) -> Iterator[DriftState]:
        """Process a stream of values, yielding states."""
        for v in values:
            yield self.update(v)


