class TestStateMachine:
    """Tests for state transitions."""

    def test_initial_state(self, default_detector):
        """Detector starts in NORMAL state."""
        assert default_detector.state == DriftState.NORMAL

    def test_normal_state_within_bounds(self, default_detector):
        """Values near target mean keep state NORMAL."""
        for _ in range(35):
            state = default_detector.update(0.05)
        assert state == DriftState.NORMAL

    def test_warning_state_detected(self, sensitive_detector):
        """Sustained small deviation triggers WARNING."""
        for _ in range(5):
            state = sensitive_detector.update(0.5)
        assert state == DriftState.WARNING

    def test_drift_state_detected(self, sensitive_detector):
        """Large deviation triggers DRIFT."""
        for _ in range(5):
            state = sensitive_detector.update(2.0)
        assert state == DriftState.DRIFT

    def test_transition_normal_to_warning(self, sensitive_detector):
        """Verify Normal → Warning transition."""
        # Stay normal
        for _ in range(5):
            sensitive_detector.update(0.0)
        assert sensitive_detector.state == DriftState.NORMAL

        # Shift to warning
        for _ in range(5):
            sensitive_detector.update(0.3)
        assert sensitive_detector.state == DriftState.WARNING

    def test_transition_warning_to_drift(self, sensitive_detector):
        """Verify Warning → Drift transition."""
        # Get to warning
        for _ in range(5):
            sensitive_detector.update(0.3)
        assert sensitive_detector.state == DriftState.WARNING

        # Escalate to drift
        for _ in range(5):
            sensitive_detector.update(2.0)
        assert sensitive_detector.state == DriftState.DRIFT

    def test_reset_clears_state(self, sensitive_detector):
        """Reset should return to NORMAL with zero accumulators."""
        for _ in range(10):
            sensitive_detector.update(2.0)
        assert sensitive_detector.state == DriftState.DRIFT

        sensitive_detector.reset()
        assert sensitive_detector.state == DriftState.NORMAL
        assert sensitive_detector.s_plus == 0.0
        assert sensitive_detector.s_minus == 0.0
        assert sensitive_detector.observation_count == 0

    def test_min_observations_gate(self, sensitive_detector):
        """State must not change before min_observations reached."""
        # Even with huge deviations, state stays NORMAL before threshold
        for _ in range(4):  # min_observations = 5
            state = sensitive_detector.update(100.0)
        assert state == DriftState.NORMAL

        # After min_observations, drift detected
        state = sensitive_detector.update(100.0)
        assert state == DriftState.DRIFT


