class TestCUSUMAlgorithm:
    """Hand-computed CUSUM value verification."""

    def test_zero_deviation_no_accumulation(self, default_detector):
        """Values equal to target mean produce zero S values."""
        default_detector.update(0.0)
        assert default_detector.s_plus == 0.0
        assert default_detector.s_minus == 0.0

    def test_positive_deviation_accumulates_s_plus(self):
        """Positive deviation accumulates in S+ only."""
        detector = DriftDetector(DriftDetectorConfig(epsilon=0.1))
        detector.update(0.5)  # deviation = 0.5, S+ = 0.5 - 0.1 = 0.4
        assert detector.s_plus == pytest.approx(0.4)
        assert detector.s_minus == 0.0

    def test_negative_deviation_accumulates_s_minus(self):
        """Negative deviation accumulates in S- only."""
        detector = DriftDetector(DriftDetectorConfig(epsilon=0.1))
        detector.update(-0.5)  # deviation = -0.5, S- = 0.5 - 0.1 = 0.4
        assert detector.s_minus == pytest.approx(0.4)
        assert detector.s_plus == 0.0

    def test_cusum_hand_computed_sequence(self):
        """Verify CUSUM against hand-computed values."""
        detector = DriftDetector(DriftDetectorConfig(epsilon=0.1))
        
        # Sequence: [0.5, 0.3, -0.2, 0.4]
        # S+ after each:
        #   0.5: max(0, 0 + 0.5 - 0.1) = 0.4
        #   0.3: max(0, 0.4 + 0.3 - 0.1) = 0.6
        #  -0.2: max(0, 0.6 - 0.2 - 0.1) = 0.3
        #   0.4: max(0, 0.3 + 0.4 - 0.1) = 0.6
        expected_s_plus = [0.4, 0.6, 0.3, 0.6]
        
        for value, expected in zip([0.5, 0.3, -0.2, 0.4], expected_s_plus):
            detector.update(value)
            assert detector.s_plus == pytest.approx(expected)

    def test_cusum_never_negative(self, sensitive_detector):
        """S values must never go negative."""
        for _ in range(100):
            sensitive_detector.update(random.uniform(-1, 1))
            assert sensitive_detector.s_plus >= 0.0
            assert sensitive_detector.s_minus >= 0.0

    def test_cusum_monotonic_increase(self, sensitive_detector):
        """S+ should monotonically increase with positive deviations."""
        prev_s_plus = 0.0
        for _ in range(10):
            sensitive_detector.update(0.5)
            assert sensitive_detector.s_plus >= prev_s_plus
            prev_s_plus = sensitive_detector.s_plus


