class TestEdgeCases:
    """Edge case handling."""

    def test_nan_rejected(self, default_detector):
        """NaN input must raise ValueError."""
        with pytest.raises(ValueError, match="NaN"):
            default_detector.update(float('nan'))

    def test_infinity_rejected(self, default_detector):
        """Infinity input must raise ValueError."""
        with pytest.raises(ValueError, match="infinite"):
            default_detector.update(float('inf'))
        with pytest.raises(ValueError, match="infinite"):
            default_detector.update(float('-inf'))

    def test_empty_stream(self, default_detector):
        """Empty stream should not change state."""
        states = list(default_detector.process_stream(iter([])))
        assert states == []
        assert default_detector.state == DriftState.NORMAL

    def test_single_observation(self, default_detector):
        """Single observation below min_observations stays NORMAL."""
        state = default_detector.update(10.0)
        assert state == DriftState.NORMAL

    def test_zero_epsilon_config(self):
        """Zero epsilon should raise even if threshold is valid."""
        with pytest.raises(ValueError):
            DriftDetectorConfig(epsilon=0.0, threshold=1.0)

    def test_extreme_values(self, sensitive_detector):
        """Very large values should trigger drift quickly."""
        for _ in range(5):
            state = sensitive_detector.update(1e6)
        assert state == DriftState.DRIFT

    def test_alternating_deviations(self, sensitive_detector):
        """Alternating positive/negative should keep S values low."""
        for i in range(20):
            value = 0.5 if i % 2 == 0 else -0.5
            sensitive_detector.update(value)
        assert sensitive_detector.state == DriftState.NORMAL


