class TestIntegration:
    """End-to-end drift detection scenarios."""

    def test_stable_system_no_drift(self, default_detector):
        """Stable system with small noise should not trigger drift."""
        random.seed(42)
        for _ in range(100):
            default_detector.update(random.gauss(0.0, 0.05))
        assert default_detector.state == DriftState.NORMAL

    def test_gradual_drift_detection(self, sensitive_detector):
        """Gradual drift should eventually be detected."""
        # Start stable
        for _ in range(10):
            sensitive_detector.update(0.0)
        
        # Gradual drift
        for i in range(1, 11):
            sensitive_detector.update(i * 0.1)
        
        assert sensitive_detector.state in (DriftState.WARNING, DriftState.DRIFT)

    def test_abrupt_drift_detection(self, sensitive_detector):
        """Abrupt shift should trigger drift quickly."""
        # Stable phase
        for _ in range(10):
            sensitive_detector.update(0.0)
        
        # Abrupt shift
        for _ in range(5):
            sensitive_detector.update(3.0)
        
        assert sensitive_detector.state == DriftState.DRIFT

    def test_recovery_after_drift(self, sensitive_detector):
        """System should recover to NORMAL after reset."""
        # Induce drift
        for _ in range(10):
            sensitive_detector.update(3.0)
        assert sensitive_detector.state == DriftState.DRIFT

        # Reset and recover
        sensitive_detector.reset()
        for _ in range(10):
            sensitive_detector.update(0.0)
        assert sensitive_detector.state == DriftState.NORMAL


